//! Media/flow-control probe with an explicitly simulated renderer. This never
//! requests input control and is not a UI presentation or latency measurement.
//! Read only a dedicated expiring controller.json generated by `deployed`.
use pb_mapper_client::sdk::{Client, ClientConfig, ConnectOptions, PathPolicy, RelayTransport};
use pb_mapper_desktop::{Invitation, VideoCodec, VideoPreferences, Viewer};
use serde::Deserialize;
use std::{
    collections::VecDeque,
    io::Write,
    time::{Duration, Instant},
};

#[derive(Deserialize)]
struct Setup {
    server: String,
    credential: String,
    transport: RelayTransport,
    invitation: String,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    let setup: Setup = serde_json::from_slice(&std::fs::read(
        args.get(1).ok_or("controller.json required")?,
    )?)?;
    let seconds: u64 = args.get(2).ok_or("seconds required")?.parse()?;
    let delay: u64 = args
        .get(3)
        .ok_or("simulated presentation delay ms required")?
        .parse()?;
    let ack: u64 = args.get(4).ok_or("ack interval ms required")?.parse()?;
    if !(5..=120).contains(&seconds) || delay > 1000 || !(10..=500).contains(&ack) {
        return Err("probe bounds: seconds 5..120, delay 0..1000, ack 10..500".into());
    }
    let path = match args.get(5).map(String::as_str) {
        Some("auto") => PathPolicy::Auto,
        Some("relay") => PathPolicy::RelayOnly,
        _ => return Err("path must be auto or relay".into()),
    };
    let mut file = args
        .get(6)
        .map(std::fs::File::create)
        .transpose()?
        .map(std::io::BufWriter::new);
    let client = Client::new(ClientConfig {
        server: setup.server,
        credential: setup.credential,
        keep_alive: true,
        namespace: None,
    })?
    .with_relay_transport(setup.transport)?;
    let viewer = Viewer::connect_with_presentation_feedback(
        &client,
        Invitation::decode(&setup.invitation)?,
        ConnectOptions {
            path,
            ..Default::default()
        },
        vec![VideoCodec::H264],
        VideoPreferences {
            max_fps: 60,
            ..Default::default()
        },
    )
    .await?;
    let result = async {
        let start = Instant::now();
        let mut changes = viewer.frames();
        let mut tick = tokio::time::interval(Duration::from_millis(ack));
        tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        let mut pending = VecDeque::with_capacity(128);
        let (mut frames, mut unique, mut keyframes, mut bytes) = (0u64, 0u64, 0u64, 0u64);
        let mut steady_unique = 0u64;
        let mut received_at = None;
        let mut intervals = Vec::new();
        while start.elapsed() < Duration::from_secs(seconds) {
            while let Some(frame) = viewer.next_frame() {
                if frame.status.state == "capture_unavailable" { return Err(frame.status.message.into()); }
                if frame.bytes.is_empty() { continue; }
                frames += 1;
                unique += u64::from(!frame.status.video.duplicate);
                if !frame.status.video.duplicate && start.elapsed() >= Duration::from_secs(5) {
                    steady_unique += 1;
                    let now = Instant::now();
                    if let Some(previous) = received_at { intervals.push(now.duration_since(previous).as_secs_f64() * 1000.0); }
                    received_at = Some(now);
                }
                keyframes += u64::from(frame.status.video.keyframe);
                bytes += frame.bytes.len() as u64;
                if let Some(file) = &mut file { file.write_all(&frame.bytes)?; }
                if pending.len() == 128 { return Err("simulated renderer queue exceeded bound".into()); }
                pending.push_back((Instant::now()+Duration::from_millis(delay), frame.status.generation, frame.status.frame_id));
            }
            let status = viewer.status();
            if status.state == "stopped" { return Err(status.message.into()); }
            tokio::select! {
                changed = changes.changed() => { changed?; }
                _ = tick.tick() => {
                    let mut last = None;
                    while pending.front().is_some_and(|(at,_,_)| *at <= Instant::now()) { last = pending.pop_front(); }
                    if let Some((_,generation,id))=last { viewer.presented(generation,id); }
                }
            }
        }
        if let Some(file) = &mut file { file.flush()?; }
        let status = viewer.status();
        println!("simulated_renderer=true seconds={:.3} delay_ms={delay} ack_ms={ack} path={} frames={frames} unique_fps={:.2} keyframes={keyframes} mbps={:.3} source_fps={:.2} video={}x{} bitrate={} dropped={} ack_rtt_ms={:.2}", start.elapsed().as_secs_f64(), status.path,unique as f64/start.elapsed().as_secs_f64(), bytes as f64*8.0/start.elapsed().as_secs_f64()/1e6,status.capture_fps,status.video.width,status.video.height,status.bitrate,status.dropped_frames,status.frame_ack_ms);
        if !intervals.is_empty() {
            intervals.sort_by(f64::total_cmp);
            println!("warmup_seconds=5 steady_unique_fps={:.2} receive_gap_p50_ms={:.2} receive_gap_p95_ms={:.2} receive_gap_max_ms={:.2}", steady_unique as f64 / (start.elapsed().as_secs_f64()-5.0), intervals[intervals.len()/2], intervals[(intervals.len()-1)*95/100], intervals[intervals.len()-1]);
        }
        Ok::<_,Box<dyn std::error::Error>>(())
    }.await;
    viewer.stop().await?;
    result
}
